<?php
require_once 'auth_check.php'; require_once 'csrf.php'; require_once __DIR__ . '/app/partials.php'; require_once __DIR__ . '/app/DonationAdminService.php';
$id = positive_int($_GET['id'] ?? null); if ($id === null) redirect_to('donation_ledger.php');
$conn = getDBConnection();
$stmt = $conn->prepare('SELECT d.*, donor.full_name, donor.phone AS donor_phone, donor.address AS donor_address, f.fname AS foundation_name FROM donations d JOIN donors donor ON donor.donor_id=d.donor_id JOIN foundations f ON f.fid=d.foundation_id WHERE d.id=?'); $stmt->bind_param('i',$id); $stmt->execute(); $donation=$stmt->get_result()->fetch_assoc(); $stmt->close(); if (!$donation) { $conn->close(); redirect_to('donation_ledger.php'); }
$history=$conn->prepare('SELECT previous_status,new_status,note,changed_by,changed_at FROM donation_status_history WHERE donation_id=? ORDER BY changed_at DESC,history_id DESC'); $history->bind_param('i',$id); $history->execute(); $historyRows=$history->get_result(); $csrfToken=generate_csrf_token();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($donation['reference_code']) ?></title><link rel="stylesheet" href="css/addashb.css"><style>.main-content{margin-left:250px;padding:24px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.card{background:#fff;padding:15px;border-radius:8px}.card small{display:block;color:#666}.history{width:100%;border-collapse:collapse;margin-top:18px}.history td,.history th{padding:10px;border:1px solid #ddd;text-align:left}textarea,select,button{display:block;width:100%;padding:9px;margin-top:8px}</style></head><body><div class="dashboard-container"><?php render_admin_sidebar('ledger'); ?><main class="main-content"><p><a href="donation_ledger.php">← Donation Ledger</a></p><h1><?= e($donation['reference_code']) ?></h1><div class="grid"><div class="card"><small>Donor</small><?= e($donation['full_name']) ?><br><?= e($donation['donor_phone']) ?><br><?= e($donation['donor_address']) ?></div><div class="card"><small>Donation</small><?= number_format((float)$donation['amount'],2) ?> MMK<br><?= e($donation['foundation_name']) ?><br><?= e($donation['payment_method']) ?></div><div class="card"><small>Verification</small><?= e($donation['payment_status']) ?><br><?= e($donation['verified_at'] ?: 'Not verified') ?><br><?= e($donation['verified_by'] ?: '') ?></div></div><section class="card" style="margin-top:16px"><h2>Update status</h2><form action="update_donation_status.php" method="post"><input type="hidden" name="csrf_token" value="<?= e($csrfToken) ?>"><input type="hidden" name="id" value="<?= (int)$id ?>"><label>Status<select name="status"><?php foreach(DONATION_STATUSES as $item): ?><option value="<?= e($item) ?>"<?= $donation['payment_status']===$item?' selected':'' ?>><?= e($item) ?></option><?php endforeach; ?></select></label><label>Reason / verification note<textarea name="note" maxlength="500" placeholder="Required for rejected or cancelled donations"></textarea></label><button type="submit">Save status change</button></form></section><h2>Status history</h2><table class="history"><tr><th>When</th><th>Change</th><th>By</th><th>Note</th></tr><?php while($row=$historyRows->fetch_assoc()): ?><tr><td><?=e($row['changed_at'])?></td><td><?=e($row['previous_status'] ?: 'Created')?> → <?=e($row['new_status'])?></td><td><?=e($row['changed_by'])?></td><td><?=e($row['note'])?></td></tr><?php endwhile; ?></table></main></div></body></html><?php $history->close();$conn->close(); ?>
